function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 100) return 'grid has 1 to 100 rows.';
  const cols = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (cols < 1 || cols > 100) return 'grid has 1 to 100 columns.';
  for (const line of grid) {
    if (!Array.isArray(line) || line.length !== cols) return 'Every row of grid has the same length.';
    for (const x of line) {
      if (!Number.isInteger(x) || x < -1000000000 || x > 1000000000) return 'Each value is an integer from -10^9 to 10^9.';
    }
  }
  return null;
}

