function findColumnWidth(grid) {
  // Count digits arithmetically instead of converting to text, one column at a time.
  const measure = (x) => {
    let count = x < 0 ? 1 : 0;
    let rest = Math.abs(x);
    do {
      count++;
      rest = Math.floor(rest / 10);
    } while (rest > 0);
    return count;
  };
  return grid[0].map((_, c) => Math.max(...grid.map(line => measure(line[c]))));
}

