function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const m = size === 'large' ? int(80, 100) : int(1, 4);
  const n = size === 'large' ? int(80, 100) : int(1, 4);
  // Each column gets its own digit cap so the widths differ from column to column.
  const caps = Array.from({ length: n }, () => int(1, 10));
  const value = (cap) => {
    if (rand() < 0.1) return 0;
    const digits = int(1, cap);
    const sign = rand() < 0.4 ? -1 : 1;
    if (digits === 10) return sign * 1000000000;
    const lowest = digits === 1 ? 1 : 10 ** (digits - 1);
    return sign * int(lowest, 10 ** digits - 1);
  };
  const grid = Array.from({ length: m }, () => caps.map(cap => value(cap)));
  return [grid];
}
